private async Task OnDoctorChanged(string value)
{
    Model.Doctor = value;
    Model.TimeSlot = string.Empty;
    serverErrors.Remove("Doctor");
    if (!string.IsNullOrEmpty(value) && Model.AppointmentDate.HasValue)
    {
        timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(value, Model.AppointmentDate.Value);
    }
}

private async Task OnDateChanged(DateTime? value)
{
    Model.AppointmentDate = value;
    Model.TimeSlot = string.Empty;
    if (value.HasValue && !string.IsNullOrEmpty(Model.Doctor))
    {
        timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, value.Value);
    }
}

